template:
@php
    // A picture deleted from the library resolves without an address: as if never picked, and one alone compares nothing.
    $first = is_array($before) && ! empty($before['url']) ? $before : null;
    $second = is_array($after) && ! empty($after['url']) ? $after : null;
    $at = is_numeric($start) ? max(0, min(100, (float) $start)) : 50;
    $beforeText = wx_text($before_label)->plain();
    $afterText = wx_text($after_label)->plain();
@endphp
@if ($first && $second)
<section class="b-compare" data-wx-block="compare">
    @if ($heading)
        <h2 class="b-compare__heading">{{ $heading }}</h2>
    @endif
    <x-webx-compare class="b-compare__compare" :before="$first" :after="$second" :start="$at" :before-label="$beforeText ?: null" :after-label="$afterText ?: null">{{ $caption }}</x-webx-compare>
</section>
@endif

styles:
.b-compare {
    container-type: inline-size;
}

.b-compare__heading {
    margin: 0 0 1em;
}

/* No margin of its own: a theme's prose spaces figures, and the frame keeps to the column. */
.b-compare__compare {
    margin: 0 auto;
}
